#!/usr/bin/env node
/**
 * Backfill AI provenance fields (model, detected_at, detection_source) on
 * gallery_images docs that are missing them, copying from the source-of-truth
 * pages.detected_images[detection_index] entry.
 *
 * WHY: the gallery image page now shows "Generated by <model>" attribution
 * (issue #2406), but only ~24% of gallery_images docs (34,627 / 144,073 as of
 * 2026-06-03) carry the `model` field — older materialization runs dropped it.
 * The page-level detections DO have it (20/20 in a random sample), so this is
 * a straight copy, no inference. Copies whatever model string is on the page
 * detection — does NOT hardcode the current worker constant.
 *
 * UPDATE-only, no deletes. Docs whose page detection is also missing the
 * model (or whose detection index no longer resolves) are left as-is and
 * counted — the UI falls back to a generic "AI-generated" chip for those.
 *
 * Modes:
 *   --limit N   Stop after examining N gallery docs
 *   --write     Actually UPDATE (default is dry-run: report what would change)
 *
 * Env: MONGODB_URI   (set -a; source .env.production.local; set +a)
 */

import { MongoClient } from 'mongodb';

const MONGODB_URI = process.env.MONGODB_URI;
if (!MONGODB_URI) {
  console.error('Missing env: MONGODB_URI');
  process.exit(1);
}

const args = process.argv.slice(2);
const WRITE = args.includes('--write');
const LIMIT = parseInt(args.find((_, i, a) => a[i - 1] === '--limit') || '0') || 0;

const BATCH = 500;

const client = new MongoClient(MONGODB_URI);
await client.connect();
const db = client.db('bookstore');
const gallery = db.collection('gallery_images');
const pages = db.collection('pages');

const counts = {
  examined: 0,
  updated: 0,
  pageMissing: 0, // source page gone (orphaned gallery doc)
  detectionMissing: 0, // detection index out of range / null entry
  noModelOnPage: 0, // page detection exists but has no model either
  byModel: {},
};

const cursor = gallery
  .find(
    { $or: [{ model: null }, { model: { $exists: false } }] },
    { projection: { id: 1, page_id: 1, detection_index: 1 } }
  )
  .batchSize(BATCH);

let batch = [];
let bulkOps = [];

async function flush() {
  if (!batch.length) return;

  // One pages fetch per batch, keyed by the `id` field (how the API looks pages up)
  const pageIds = [...new Set(batch.map((g) => g.page_id))];
  const pageDocs = await pages
    .find({ id: { $in: pageIds } }, { projection: { id: 1, detected_images: 1 } })
    .toArray();
  const pageMap = new Map(pageDocs.map((p) => [p.id, p]));

  for (const g of batch) {
    const page = pageMap.get(g.page_id);
    if (!page) {
      counts.pageMissing++;
      continue;
    }
    const det = page.detected_images?.[g.detection_index];
    if (!det) {
      counts.detectionMissing++;
      continue;
    }
    // Copy whatever provenance the page detection has — model, run date,
    // source. A detection missing the model may still carry detected_at.
    const $set = {};
    if (det.model) $set.model = det.model;
    if (det.detected_at) $set.detected_at = det.detected_at;
    if (det.detection_source) $set.detection_source = det.detection_source;

    if (!det.model) counts.noModelOnPage++;
    if (!Object.keys($set).length) continue;

    if (det.model) counts.byModel[det.model] = (counts.byModel[det.model] || 0) + 1;
    counts.updated++;
    if (WRITE) {
      bulkOps.push({ updateOne: { filter: { _id: g._id }, update: { $set } } });
    }
  }

  if (WRITE && bulkOps.length) {
    const res = await gallery.bulkWrite(bulkOps, { ordered: false });
    if (res.modifiedCount !== bulkOps.length) {
      console.warn(`  bulkWrite: ${res.modifiedCount}/${bulkOps.length} modified`);
    }
    bulkOps = [];
  }
  batch = [];
}

for await (const doc of cursor) {
  batch.push(doc);
  counts.examined++;
  if (batch.length >= BATCH) {
    await flush();
    if (counts.examined % 10000 < BATCH) {
      console.log(
        `  ...${counts.examined} examined, ${counts.updated} ${WRITE ? 'updated' : 'would update'}`
      );
    }
  }
  if (LIMIT && counts.examined >= LIMIT) break;
}
await flush();

console.log(`\n${WRITE ? 'WROTE' : 'DRY RUN (use --write to apply)'}`);
console.log(`  examined:          ${counts.examined}`);
console.log(`  ${WRITE ? 'updated' : 'would update'}:      ${counts.updated}`);
console.log(`  page missing:      ${counts.pageMissing}`);
console.log(`  detection missing: ${counts.detectionMissing}`);
console.log(`  no model on page:  ${counts.noModelOnPage}`);
console.log(`  by model:`, counts.byModel);

const remaining = await gallery.countDocuments({
  $or: [{ model: null }, { model: { $exists: false } }],
});
console.log(`  gallery_images still without model: ${remaining}`);

await client.close();
